-- Catálogos oficiales SAT Carta Porte 3.1. Fuente: CatalogosCartaPorte31.xls, publicado 17/06/2024.
BEGIN;
CREATE TABLE IF NOT EXISTS sat.configuraciones_autotransporte (clave_config_autotransporte_sat varchar(20) PRIMARY KEY, descripcion text NOT NULL, numero_ejes integer NULL, numero_llantas varchar(20) NULL, remolque varchar(5) NULL, fecha_inicio_vigencia date NULL, fecha_fin_vigencia date NULL);
CREATE TABLE IF NOT EXISTS sat.tipos_permiso (clave_tipo_permiso_sat varchar(20) PRIMARY KEY, descripcion text NOT NULL, clave_transporte varchar(20) NULL, fecha_inicio_vigencia date NULL, fecha_fin_vigencia date NULL);
CREATE INDEX IF NOT EXISTS configuraciones_autotransporte_descripcion_idx ON sat.configuraciones_autotransporte (lower(descripcion));
CREATE INDEX IF NOT EXISTS tipos_permiso_descripcion_idx ON sat.tipos_permiso (lower(descripcion));
COMMIT;
